-- F3.65/F3.66: partner action planning and immutable accountability history.
-- Already applied to the linked Supabase project on 2026-11-24.
create table if not exists public.partner_relationship_action_plans(id uuid primary key default gen_random_uuid(),account_id uuid not null references public.partner_accounts(id) on delete restrict,title text not null check(length(trim(title)) between 3 and 180),details text not null check(length(trim(details)) between 8 and 2000),priority text not null check(priority in ('CRITICAL','HIGH','MEDIUM','LOW')),status text not null default 'OPEN' check(status in ('OPEN','IN_PROGRESS','WAITING','RESOLVED','CANCELLED')),owner_user_id uuid,due_at date,decision text check(decision in ('RECOVER','RENEW','RENEGOTIATE','CONTINUE','TERMINATE','OTHER')),resolution_note text check(resolution_note is null or length(trim(resolution_note)) between 8 and 2000),created_by uuid not null,updated_by uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),resolved_at timestamptz);
create index if not exists partner_rel_action_account_status_f365_idx on public.partner_relationship_action_plans(account_id,status,due_at);
alter table public.partner_relationship_action_plans enable row level security;
revoke all on public.partner_relationship_action_plans from anon,authenticated;
grant select,insert,update on public.partner_relationship_action_plans to authenticated;
create policy partner_rel_action_superadmin_manage on public.partner_relationship_action_plans for all to authenticated using (public.is_super_admin()) with check (public.is_super_admin());
create table if not exists public.partner_relationship_action_history(id bigint generated always as identity primary key,action_id uuid not null references public.partner_relationship_action_plans(id) on delete restrict,account_id uuid not null references public.partner_accounts(id) on delete restrict,actor_user_id uuid,event_type text not null,snapshot jsonb not null,note text,occurred_at timestamptz not null default now());
create index if not exists partner_rel_action_history_action_f365_idx on public.partner_relationship_action_history(action_id,occurred_at desc);
alter table public.partner_relationship_action_history enable row level security;
revoke all on public.partner_relationship_action_history from anon,authenticated;
grant select,insert on public.partner_relationship_action_history to authenticated;
create policy partner_rel_action_history_superadmin_read on public.partner_relationship_action_history for select to authenticated using (public.is_super_admin());
create policy partner_rel_action_history_superadmin_insert on public.partner_relationship_action_history for insert to authenticated with check (public.is_super_admin());
create or replace function public.partner_relationship_action_history_capture_f365() returns trigger language plpgsql security invoker set search_path=pg_catalog,public,auth,pg_temp as $$ begin if tg_op='INSERT' then insert into public.partner_relationship_action_history(action_id,account_id,actor_user_id,event_type,snapshot,note) values(new.id,new.account_id,new.created_by,'CREATED',to_jsonb(new),new.details);return new;else insert into public.partner_relationship_action_history(action_id,account_id,actor_user_id,event_type,snapshot,note) values(new.id,new.account_id,new.updated_by,case when old.status is distinct from new.status then 'STATUS_CHANGED' else 'UPDATED' end,to_jsonb(new),coalesce(new.resolution_note,new.details));return new;end if;end;$$;
create trigger partner_relationship_action_history_capture_f365 after insert or update on public.partner_relationship_action_plans for each row execute function public.partner_relationship_action_history_capture_f365();
create or replace function public.partner_relationship_action_history_immutable_f365() returns trigger language plpgsql security invoker set search_path=pg_catalog,public,auth,pg_temp as $$ begin raise exception 'HISTORY_IMMUTABLE';end;$$;
create trigger partner_relationship_action_history_immutable_f365 before update or delete on public.partner_relationship_action_history for each row execute function public.partner_relationship_action_history_immutable_f365();
create or replace function public.admin_partner_relationship_action_dashboard_f365() returns jsonb language plpgsql security invoker set search_path=pg_catalog,public,auth,pg_temp as $$ declare v jsonb;begin if auth.uid() is null or not public.is_super_admin() then raise exception 'FORBIDDEN' using errcode='42501';end if;select jsonb_build_object('actions',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'account_id',a.account_id,'account_name',p.name,'title',a.title,'details',a.details,'priority',a.priority,'status',a.status,'owner_user_id',a.owner_user_id,'due_at',a.due_at,'decision',a.decision,'resolution_note',a.resolution_note,'created_at',a.created_at,'updated_at',a.updated_at,'history',coalesce(h.history,'[]'::jsonb)) order by case a.priority when 'CRITICAL' then 1 when 'HIGH' then 2 when 'MEDIUM' then 3 else 4 end,a.due_at nulls last,a.created_at desc) from public.partner_relationship_action_plans a join public.partner_accounts p on p.id=a.account_id left join lateral(select jsonb_agg(jsonb_build_object('event_type',x.event_type,'snapshot',x.snapshot,'note',x.note,'occurred_at',x.occurred_at,'actor_user_id',x.actor_user_id) order by x.occurred_at desc) history from public.partner_relationship_action_history x where x.action_id=a.id) h on true),'[]'::jsonb)) into v;return v;end;$$;
revoke all on function public.admin_partner_relationship_action_dashboard_f365() from public,anon;
grant execute on function public.admin_partner_relationship_action_dashboard_f365() to authenticated;